import json, glob, re, collections
S = collections.defaultdict
cases = {}; types = S(collections.Counter); results = S(collections.Counter); cited = S(set); nsess = collections.Counter()
verd = S(lambda: S(collections.Counter))
for f in glob.glob("runs/*/sessions/*.json"):
    d = json.load(open(f)); c = d["case"]; cid = c["case_id"]; cases[cid] = c; nsess[cid] += 1
    tr = d.get("trace") or []
    for i, ev in enumerate(tr):
        m = ev["move"]
        if ev["actor"] == "buyer":
            cl = (m.get("interpreted") or {}).get("claims") or []
            for r in m.get("refs") or []: cited[cid].add(r)
            # the supplier's answer to this move
            nxt = next((e for e in tr[i+1:] if e["actor"] == m.get("supplier_id")), None)
            res = (nxt or {}).get("move", {}).get("claim_results") or []
            for j, k in enumerate(cl):
                types[cid][k["type"]] += 1
                r = next((x["result"] for x in res if x.get("index") == j), "none")
                results[k["type"]][r] += 1
        else:
            for r in ev.get("reasons") or []:
                mm = re.search(r"(?:checked|As to) the ([a-z ]+?) data you cited[;,] (.*)", r)
                if mm:
                    v = "took" if "took it into account" in mm.group(2) else "no_change" if "does not change" in mm.group(2) else "fair_point" if "fair point" in mm.group(2) else "other:" + mm.group(2)[:40]
                    verd[mm.group(1)][cid][v] += 1
print("sessions per case", dict(sorted(nsess.items())))
print("\nclaim results by arena type"); [print(" ", t, dict(c)) for t, c in results.items()]
print("\narena claim types per case (count over sessions)")
for cid in sorted(types): print(" ", cid, dict(types[cid]))
print("\nverdict sentences by data kind: total / per case")
for kind, pc in verd.items():
    tot = collections.Counter()
    for c in pc.values(): tot.update(c)
    print(" ", kind, dict(tot))
    for cid in sorted(pc): print("      ", cid, dict(pc[cid]))
json.dump({"cases": cases, "cited": {k: sorted(v) for k, v in cited.items()}}, open("/tmp/claude-1000/-home-vector-Desktop-Programming-EHLFinal2026/d3036451-9cdd-4027-9775-b8e9ca438766/scratchpad/cases.json", "w"))
E
python3 -I /tmp/claude-1000/-home-vector-Desktop-Programming-EHLFinal2026/d3036451-9cdd-4027-9775-b8e9ca438766/scratchpad/audit1.py

