cat > /tmp/claude-1000/-home-vector-Desktop-Programming-EHLFinal2026/d3036451-9cdd-4027-9775-b8e9ca438766/scratchpad/audit2.py <<'E'
import json, csv, collections
SP = "/tmp/claude-1000/-home-vector-Desktop-Programming-EHLFinal2026/d3036451-9cdd-4027-9775-b8e9ca438766/scratchpad/"
K = "../negotiation-arena-kit/data/"
facts = json.load(open(K + "facts.json")); st = json.load(open(SP + "cases.json"))
drivers = collections.defaultdict(list)
for r in csv.DictReader(open(K + "data/cost_drivers.csv")): drivers[r["part_id"]].append((r["series_id"], r["weight"]))
for cid in sorted(st["cases"]):
    c = st["cases"][cid]; parts = set(c["parts"]); sups = set(c["suppliers"]); cited = set(st["cited"].get(cid, []))
    print(f"\n== {cid} {c['type']} goal={c['buyer'].get('category_goal')} parts={sorted(parts)} sups={sorted(sups)}")
    print("   case refs:", c.get("refs"), "| alt:", json.dumps(c.get("alternative") or c["buyer"].get("alternative"))[:200])
    for ref in c.get("refs") or []:
        if ref.startswith("quote:"): print("   ", ref, facts.get(ref), "CITED" if ref in cited else "never cited")
    by = collections.defaultdict(list)
    for k, v in facts.items():
        p = k.split(":")[0]
        if p == "idx": continue
        if v.get("part") in parts and (p in ("fc", "cost", "rfq") or v.get("supplier") in sups or p == "quote"): by[p].append(k)
        elif v.get("supplier") in sups and p in ("sc", "ctr", "doc", "news", "qn") and (p != "qn" or v.get("part") in parts): by[p].append(k)
    for p in ("po", "fc", "cost", "sc", "qn", "ctr", "doc", "news", "quote"):
        ids = by.get(p, []); n = len([i for i in ids if i in cited])
        extra = ""
        if p == "quote": extra = " " + "; ".join(f"{i}:{facts[i]['supplier']}@{facts[i]['unit_price']}({facts[i]['date']})" + ("*" if i in cited else "") for i in sorted(ids)[-6:])
        if p == "news": extra = " " + "; ".join(f"{i}:{facts[i]['topic']}" + ("*" if i in cited else "") for i in ids)
        if p == "doc": extra = " " + "; ".join(f"{i}:{facts[i]['type']},{facts[i]['title'][:30]},days={facts[i]['days']}" + ("*" if i in cited else "") for i in sorted(ids)[-4:])
